#include <stdint.h>
#include <stddef.h>
#include <stdio.h>
#include "systolic_stub.h"

/* generated by ICDeCompiler */
void batch_matmul_i16(int16_t A[1][8][8], int16_t B[1][8][8], int32_t C[1][8][8]);

int main(void) {
    int16_t A[1][8][8], B[1][8][8];
    int32_t C[1][8][8];
    int32_t ref[8][8];

    for (int i = 0; i < 8; i++) {
        for (int j = 0; j < 8; j++) {
            A[0][i][j] = (int16_t)(i * 2 + j);
            B[0][i][j] = (int16_t)(j - i);
            C[0][i][j] = 0;
        }
    }

    for (int i = 0; i < 8; i++) {
        for (int j = 0; j < 8; j++) {
            int32_t acc = 0;
            for (int k = 0; k < 8; k++)
                acc += (int32_t)A[0][i][k] * (int32_t)B[0][k][j];
            ref[i][j] = acc;
        }
    }

    batch_matmul_i16(A, B, C);

    int mismatches = 0;
    for (int i = 0; i < 8; i++) {
        for (int j = 0; j < 8; j++) {
            if (C[0][i][j] != ref[i][j]) {
                if (mismatches < 5)
                    printf("mismatch at [%d][%d]: got %d, expected %d\n",
                           i, j, C[0][i][j], ref[i][j]);
                mismatches++;
            }
        }
    }

    if (mismatches == 0) {
        printf("OK: batch matmul matches reference\n");
        return 0;
    }
    printf("FAIL: %d mismatches\n", mismatches);
    return 1;
}